def render(template, context):
    """
    Render a tiny template language.

    Parameters
    ----------
    template : str
        The template string.
    context : dict
        Mapping of variable names to values.

    Returns
    -------
    str
        Rendered output.

    Raises
    ------
    ValueError
        If the template contains syntax errors or unknown filters.
    """
    # ---------- Lexer ----------
    def lexer(tpl):
        tokens = []
        i = 0
        n = len(tpl)
        while i < n:
            if tpl.startswith("{{", i):
                j = tpl.find("}}", i + 2)
                if j == -1:
                    tokens.append(("text", tpl[i:]))
                    break
                tokens.append(("var", tpl[i + 2:j]))
                i = j + 2
            elif tpl.startswith("{%", i):
                j = tpl.find("%}", i + 2)
                if j == -1:
                    tokens.append(("text", tpl[i:]))
                    break
                tokens.append(("block", tpl[i + 2:j]))
                i = j + 2
            else:
                next_var = tpl.find("{{", i)
                next_block = tpl.find("{%", i)
                next_pos = min(
                    [pos for pos in [next_var, next_block] if pos != -1] or [n]
                )
                tokens.append(("text", tpl[i:next_pos]))
                i = next_pos
        return tokens

    # ---------- Path evaluation ----------
    def get_value(ctx, path):
        parts = path.split(".")
        val = ctx
        for part in parts:
            if isinstance(val, dict):
                if part in val:
                    val = val[part]
                else:
                    return None
            elif isinstance(val, list):
                if part.isdigit():
                    idx = int(part)
                    if 0 <= idx < len(val):
                        val = val[idx]
                    else:
                        return None
                else:
                    return None
            else:
                return None
        return val

    # ---------- Filter application ----------
    def apply_filter(val, filt):
        if filt is None:
            return val
        if val is None:
            val_str = ""
        else:
            val_str = str(val)
        if filt == "upper":
            return val_str.upper()
        if filt == "lower":
            return val_str.lower()
        if filt == "title":
            return val_str.title()
        if filt == "length":
            return 0 if val is None else len(val)
        raise ValueError(f"Unknown filter: {filt}")

    # ---------- Node classes ----------
    class Node:
        def render(self, ctx):
            raise NotImplementedError

    class TextNode(Node):
        def __init__(self, text):
            self.text = text

        def render(self, ctx):
            return self.text

    class VarNode(Node):
        def __init__(self, path, filt):
            self.path = path
            self.filt = filt

        def render(self, ctx):
            val = get_value(ctx, self.path)
            if val is None:
                val = ""
            val = apply_filter(val, self.filt)
            return str(val)

    class IfNode(Node):
        def __init__(self, path, negated, true_branch, false_branch):
            self.path = path
            self.negated = negated
            self.true_branch = true_branch
            self.false_branch = false_branch

        def render(self, ctx):
            val = get_value(ctx, self.path)
            truth = bool(val)
            if self.negated:
                truth = not truth
            branch = self.true_branch if truth else self.false_branch
            return "".join(node.render(ctx) for node in branch)

    class ForNode(Node):
        def __init__(self, var_name, path, body):
            self.var_name = var_name
            self.path = path
            self.body = body

        def render(self, ctx):
            iterable = get_value(ctx, self.path)
            if iterable is None or not isinstance(iterable, list):
                iterable = []
            out = []
            for item in iterable:
                new_ctx = ctx.copy()
                new_ctx[self.var_name] = item
                out.append("".join(node.render(new_ctx) for node in self.body))
            return "".join(out)

    # ---------- Parser ----------
    def parse(tokens):
        def parse_nodes(idx, stop_tokens):
            nodes = []
            while idx < len(tokens):
                typ, content = tokens[idx]
                if typ == "text":
                    nodes.append(TextNode(content))
                    idx += 1
                elif typ == "var":
                    path, filt = parse_var(content)
                    nodes.append(VarNode(path, filt))
                    idx += 1
                elif typ == "block":
                    tag = content.strip()
                    if tag in stop_tokens:
                        return nodes, idx + 1
                    if tag.startswith("if "):
                        node, idx = parse_if(idx)
                        nodes.append(node)
                    elif tag.startswith("for "):
                        node, idx = parse_for(idx)
                        nodes.append(node)
                    else:
                        raise ValueError(f"Unknown tag: {tag}")
                else:
                    idx += 1
            return nodes, idx

        def parse_var(text):
            text = text.strip()
            if "|" in text:
                path_part, filter_part = text.split("|", 1)
                return path_part.strip(), filter_part.strip()
            return text, None

        def parse_if(idx):
            typ, content = tokens[idx]
            tag = content.strip()
            rest = tag[3:].strip()
            negated = False
            if rest.startswith("not "):
                negated = True
                rest = rest[4:].strip()
            path = rest
            if not path:
                raise ValueError("Missing path in if")
            idx += 1
            true_branch, idx = parse_nodes(idx, {"else", "endif"})
            if tokens[idx - 1][1].strip() == "else":
                false_branch, idx = parse_nodes(idx, {"endif"})
            else:
                false_branch = []
            return IfNode(path, negated, true_branch, false_branch), idx

        def parse_for(idx):
            typ, content = tokens[idx]
            tag = content.strip()
            rest = tag[4:].strip()
            if " in " not in rest:
                raise ValueError("Invalid for syntax")
            var_name, path = rest.split(" in ", 1)
            var_name = var_name.strip()
            path = path.strip()
            if not var_name or not path:
                raise ValueError("Invalid for syntax")
            idx += 1
            body, idx = parse_nodes(idx, {"endfor"})
            return ForNode(var_name, path, body), idx

        nodes, final_idx = parse_nodes(0, set())
        if final_idx != len(tokens):
            raise ValueError("Unclosed tags")
        return nodes

    # ---------- Render ----------
    tokens = lexer(template)
    nodes = parse(tokens)
    return "".join(node.render(context) for node in nodes)
