                else:
                    idx += 1
            return nodes, idx

        def parse_var(text):
            text = text.strip()
            if "|" in text:
                path_part, filter_part = text.split("|", 1)
                return path_part.strip(), filter_part.strip()
            return text, None

        def parse_if(idx):
            typ, content = tokens[idx]
            tag = content.strip()
            rest = tag[3:].strip()
            negated = False
            if rest.startswith("not "):
                negated = True
                rest = rest[4:].strip()
            path = rest
            if not path:
                raise ValueError("Missing path in if")
            idx += 1
            true_branch, idx = parse_nodes(idx, {"else", "endif"})
            if tokens[idx - 1][1].strip() == "else":
                false_branch, idx = parse_nodes(idx, {"endif"})
            else:
                false_branch = []
            return IfNode(path, negated, true_branch, false_branch), idx

        def parse_for(idx):
            typ, content = tokens[idx]
            tag = content.strip()
            rest = tag[4:].strip()
            if " in " not in rest:
                raise ValueError("Invalid for syntax")
            var_name, path = rest.split(" in ", 1)
            var_name = var_name.strip()
            path = path.strip()
            if not var_name or not path:
                raise ValueError("Invalid for syntax")
            idx += 1
            body, idx = parse_nodes(idx, {"endfor"})
            return ForNode(var_name, path, body), idx

        nodes, final_idx = parse_nodes(0, set())
        if final_idx != len(tokens):
            raise ValueError("Unclosed tags")
        return nodes

    # ---------- Render ----------
    tokens = lexer(template)
    nodes = parse(tokens)
    return "".join(node.render(context) for node in nodes)
